//! Phase-0 oracle: the Rust XNYS calendar must reproduce
//! `exchange_calendars` sessions exactly.
//!
//! The fixture is generated by `src/lake/tests/oracle/generate.py` from the
//! reference Python implementation.

use lake_contracts::{xnys_sessions, Date};
use serde_json::Value;

fn oracle() -> Vec<Value> {
    serde_json::from_str(include_str!("oracle/xnys_sessions.json")).expect("session oracle")
}

#[test]
fn every_oracle_session_matches_the_rust_calendar() {
    let entries = oracle();
    assert!(
        entries.len() > 3_000,
        "oracle should cover 2015..2027, got {} sessions",
        entries.len()
    );
    for entry in &entries {
        let raw_date = entry["date"].as_str().expect("date");
        let date = Date::parse(raw_date).expect("valid oracle date");
        let sessions = xnys_sessions(date, date).expect("sessions");
        assert_eq!(
            sessions.len(),
            1,
            "expected exactly one session for {raw_date}"
        );
        let session = &sessions[0];
        assert_eq!(
            session.open_time.isoformat_seconds_z(),
            entry["open"].as_str().expect("open"),
            "open mismatch on {raw_date}"
        );
        assert_eq!(
            session.close_time.isoformat_seconds_z(),
            entry["close"].as_str().expect("close"),
            "close mismatch on {raw_date}"
        );
    }
}

#[test]
fn oracle_covers_early_closes_and_adhoc_closures() {
    let entries = oracle();
    let dates: std::collections::BTreeSet<&str> = entries
        .iter()
        .map(|entry| entry["date"].as_str().expect("date"))
        .collect();
    assert!(!dates.contains("2018-12-05"), "Bush funeral closure");
    assert!(!dates.contains("2025-01-09"), "Carter funeral closure");
    let early = entries
        .iter()
        .find(|entry| entry["date"] == "2024-11-29")
        .expect("black friday");
    assert_eq!(early["close"], "2024-11-29T18:00:00Z");
    let christmas_eve = entries
        .iter()
        .find(|entry| entry["date"] == "2024-12-24")
        .expect("christmas eve");
    assert_eq!(christmas_eve["close"], "2024-12-24T18:00:00Z");
}
